package com.pulselens.analytics.entity;
import jakarta.persistence.*;import java.time.LocalDateTime;
@Entity @Table(name="social_posts") public class SocialPost {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id;private String platform;private String authorName;@Column(name="post_text",nullable=false,columnDefinition="TEXT") private String postText;@Column(length=1000) private String postUrl;private long likesCount;private long sharesCount;private long commentsCount;@Column(length=500) private String hashtagText;private String sentiment;private LocalDateTime postedAt;
 public Long getId(){return id;}public String getPlatform(){return platform;}public void setPlatform(String v){platform=v;}public String getAuthorName(){return authorName;}public void setAuthorName(String v){authorName=v;}public String getPostText(){return postText;}public void setPostText(String v){postText=v;}public String getPostUrl(){return postUrl;}public void setPostUrl(String v){postUrl=v;}public long getLikesCount(){return likesCount;}public void setLikesCount(long v){likesCount=v;}public long getSharesCount(){return sharesCount;}public void setSharesCount(long v){sharesCount=v;}public long getCommentsCount(){return commentsCount;}public void setCommentsCount(long v){commentsCount=v;}public String getHashtagText(){return hashtagText;}public void setHashtagText(String v){hashtagText=v;}public String getSentiment(){return sentiment;}public void setSentiment(String v){sentiment=v;}public LocalDateTime getPostedAt(){return postedAt;}public void setPostedAt(LocalDateTime v){postedAt=v;}
}
